version.content:
pipeline {
    agent any
     parameters {
        choice(
            name: 'OPERATION',
            choices: ['deploy', 'rollback', 'start', 'stop', 'restart'],
            description: '操作类型：部署/回滚/启动/停止/重启'
        )
        string(name: 'ENV', defaultValue: 'PROD', description: '环境：DEV/TEST/UAT/PRE/PROD')
        string(name: 'APP_NAME', defaultValue: 'e-certificate', description: '应用名称')
        string(name: 'GIT_BRANCH', defaultValue: 'dev', description: '分支')
    }
    environment {
        GROUP_NAME = ''
        PROJECT_NAME = ''
        VERSION = ''
        // PORT = '18848'
        // REMOTE_HOST = '20.48.1.66'
        // REMOTE_USER = 'root'
        // REMOTE_CREDENTIALS_ID = 'jenkins-server-ssh-private-key'
        // TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('Asia/Shanghai'))

        // Git 配置 
        // GIT_URL = 'http://20.48.1.132:12001/devsecops/opsservice/ansible-playbook.git'
        // GIT_BRANCH = 'main'
        // GIT_CREDENTIALS_ID = '668d4a76-2bba-4aed-9693-5b6e5625e4a7'

        // AWX 配置（仅部署时触发）
        AWX_URL = 'http://20.12.18.199:8013'
        AWX_WEBHOOK_TOKEN = 'IhDJxIyQvZKaawrdSoDV'
        AWX_JT_ID = '16' //ansible-awx 模版ID
        TARGET_HOST = '20.31.130.26'
        COMPOSE_PATH = '/data/e-certificate'

        // 凭据 ID（需要在 Jenkins 中配置）
        HARBOR_CREDENTIALS_ID = 'harbor-credential-id'  // Harbor 用户名密码
        MINIO_CREDS = 'c44a58e0-b640-471c-ab76-a667bb5e4fcb'  // 使用在 Jenkins 中配置的凭据ID
        ARTIFACT_BUCKET = 'deploy'   // 定义统一使用的存储桶名称
    }

    stages {
        stage('Git Checkout') {
            steps {
                echo "Checking out code from branch: ${params.GIT_BRANCH}"
                checkout scmGit(
                    branches: [[name: "${params.GIT_BRANCH}"]],
                    extensions: [],
                    userRemoteConfigs: [[
                        credentialsId: 'SSH-KEY-FOR-GITLAB',
                        url: "${GIALAB_ADDRESS}/dengbin/e-certificate-platform.git"
                    ]]
                )
            }
        }

        stage('Mvn Compile') {
            steps {
                script {
                    def pom = readMavenPom file: 'pom.xml'
                    GROUP_NAME = pom.groupId
                    PROJECT_NAME = pom.artifactId
                    VERSION = pom.version

                    echo "Building project: ${GROUP_NAME}/${PROJECT_NAME}-${VERSION}"
                    sh "mvn clean install -Dmaven.test.skip=true -Pprod"
                }
            }
        }

        stage('Upload Build Artifact') {
            steps {
                echo "Uploading build artifact to MinIO"
                echo "target/${PROJECT_NAME}-${VERSION}.jar"
                minio(
                    credentialsId: "${MINIO_CREDS}",
                    host: 'http://20.12.18.199:8013',
                    bucket: "${ARTIFACT_BUCKET}",
                    includes: "target/${PROJECT_NAME}-${VERSION}.jar",
                    // targetFolder: "/"
                    targetFolder: "releases/${env.JOB_NAME}/${env.BUILD_NUMBER}",
                    // pathStyle: true   // ← 关键
                )
            }
        }

        stage('触发 AWX 部署') {
            // when { expression { params.OPERATION == 'deploy' } }
            steps {
                script {
                    def payload = """{
                        "event_type": "deploy",
                        "ref": "${params.GIT_BRANCH}",
                        "image": {
                            "registry": "${DOCKER_REGISTRY}",
                            "project": "devops",
                            "name": "${params.APP_NAME}",
                            "tag": "${env.LATEST_IMAGE_TAG}",
                            "full": "${env.DOCKER_IMAGE_PREFIX}/${params.APP_NAME}:${env.LATEST_IMAGE_TAG}"
                        },
                        "target": {
                            "host": "${TARGET_HOST}",
                            "compose_path": "${COMPOSE_PATH}",
                            "service": "${params.APP_NAME}",
                            "build_id": "${env.BUILD_ID}",
                            "artifact_url": "http://20.31.132.40:8013/artifacts/${ARTIFACT_BUCKET}/releases/${env.JOB_NAME}/${env.BUILD_NUMBER}/${PROJECT_NAME}-${VERSION}.jar",
                            "artifact_name": "${PROJECT_NAME}-${VERSION}.jar",
                            "bucket_name":"${ARTIFACT_BUCKET}",
                            "object_key":"/releases/${env.JOB_NAME}/${env.BUILD_NUMBER}/${PROJECT_NAME}-${VERSION}.jar",
                            "app_env_vars": {"NACOS_SERVER": "39.129.77.191:9000"},
                            "java_proxy_host":"172.17.44.8",
                            "java_proxy_port":"7897"
                        }
                    }"""
                    sh """
                        curl -s -X POST \
                            -H "Content-Type: application/json" \
                            -H "X-Custom-Webhook-Token: ${AWX_WEBHOOK_TOKEN}" \
                            -d '${payload}' \
                            ${AWX_URL}/api/v2/job_templates/${AWX_JT_ID}/custom/
                    """
                    echo "AWX 触发完成（异步）"
                }
            }
        }
    }
    post {
        always {
            echo '========================================'
            echo " Pipeline 执行完成 "
            echo " 最终状态: ${currentBuild.result ?: 'SUCCESS'}"
            echo '========================================'
        }
        success {
            echo "✅ 操作成功完成!"
        }
        failure {
            echo "❌ 操作失败，请检查日志!"
        }
    }
}
